#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU
# that appears in movements.log, plus every catalog SKU (SKU-9) even when it
# has no movements or nets to zero.
awk 'NR == FNR { net[$1] += ($2 == "receipt" ? $3 : -$3); next }
     FNR == NR { net[$1] += 0 }
     END { for (sku in net) print sku, net[sku] + 0 }' \
    movements.log <(echo "SKU-9") | sort > stock.txt

